package main

import "fmt"

func main() {
	var d int
	var s, t string

	// 1. Lendo a quantidade de dindins
	fmt.Scan(&d)

	// Criando os vetores para guardar os sabores e os turnos
	var vetSabor []string = make([]string, d)
	var vetTurno []string = make([]string, d)

	// 2. Loop para ler todos os dados e guardar nos vetores
	for i := 0; i < d; i++ {
		fmt.Scan(&s, &t)
		vetSabor[i] = s
		vetTurno[i] = t
	}

	// Criando as nossas "caixas" contadoras (todas começam em 0)
	qtdChocolate := 0
	qtdLimao := 0
	qtdManha := 0
	qtdTarde := 0

	// 3. O Loop de contagem: passando pelos vetores e somando nas caixas
	for i := 0; i < d; i++ {
		// Testando o sabor
		if vetSabor[i] == "c" {
			qtdChocolate++
		} else if vetSabor[i] == "l" {
			qtdLimao++
		}

		// Testando o turno
		if vetTurno[i] == "m" {
			qtdManha++
		} else if vetTurno[i] == "t" {
			qtdTarde++
		}
	}

	// 4. Verificando o sabor MAIS vendido (Maior valor)
	if qtdChocolate > qtdLimao {
		fmt.Println("c")
	} else if qtdLimao > qtdChocolate {
		fmt.Println("l")
	} else {
		fmt.Println("empate")
	}

	// 5. Verificando o turno MAIS vago (Menor valor)
	if qtdManha < qtdTarde {
		fmt.Println("m")
	} else if qtdTarde < qtdManha {
		fmt.Println("t")
	} else {
		fmt.Println("empate")
	}
}
